function loadBeyModel(bey,url){
  beyLoader.load(url,gltf=>{
    const model=gltf.scene;model.updateMatrixWorld(true);
    const bounds=new THREE.Box3().setFromObject(model),size=bounds.getSize(new THREE.Vector3());
    const diameter=Math.max(size.x,size.z),largest=Math.max(diameter,size.y);
    if(!Number.isFinite(largest)||largest<1e-4)return;
    const scale=1.65/largest;model.scale.setScalar(scale);
    model.position.set(-(bounds.min.x+bounds.max.x)*.5*scale,-bounds.min.y*scale,-(bounds.min.z+bounds.max.z)*.5*scale);
